<?php use Namira\PublicPresentation as P;$people=$people?:[['id'=>$im['martyr_id']]+$im];$humanTitle=implode('، ',array_map([P::class,'personName'],$people)); ?>
<div class="panel image-detail"><a href="<?= e(url('media',['id'=>$im['id'],'size'=>'large'])) ?>"><img class="preview" src="<?= e(url('media',['id'=>$im['id'],'size'=>'large'])) ?>" alt="<?= e($humanTitle) ?>"></a><div><p class="muted">آرشیو تصاویر نامیرا</p><h1><?= e($humanTitle) ?></h1>
<?php if($topics??[]): ?><div class="image-topics" aria-label="دسته‌بندی موضوعی"><?php foreach($topics as $topic): ?><span><?= e($topic) ?></span><?php endforeach ?></div><?php endif ?>
<dl class="image-facts"><div><dt>کد تصویر</dt><dd dir="ltr"><?= e(Namira\ImageCode::format((int)$im['id'])) ?></dd></div><div><dt>حجم فایل</dt><dd><?= P::fileSize((int)$im['bytes']) ?></dd></div>
<?php if($creators):foreach($creators as $creator): ?><div><dt><?= e(['designer'=>'طراح','photographer'=>'عکاس','restorer'=>'مرمت‌گر','editor'=>'ویرایشگر'][$creator['creator_role']]??$creator['creator_role']) ?></dt><dd><?php if($creator['public_visible']&&!$creator['archived']): ?><a class="image-artist-link" href="<?= e(url('artist',['id'=>$creator['artist_id']])) ?>"><?= e($creator['credit_name']) ?></a><?php else: ?><?= e($creator['credit_name']) ?><?php endif ?></dd></div><?php endforeach;elseif(P::meaningful($im['designer']??'')): ?><div><dt>طراح</dt><dd><?= e($im['designer']) ?></dd></div><?php endif ?></dl>
<?php foreach(['description'=>'','source_text'=>'منبع: '] as $key=>$label):if(!P::meaningful($im['publication'][$key]??null))continue; ?><p class="prose"><?= e($label).nl2br(e($im['publication'][$key])) ?></p><?php endforeach ?>
<?php if(P::meaningful($im['license_text']??null)): ?><p class="prose"><?= e($im['license_text']) ?></p><?php endif ?>
<div class="image-actionbar"><nav class="related-people" aria-label="پرونده شهید"><?php foreach($people as $person): ?><a class="outline person-page-button" href="<?= e(url('profile',['id'=>$person['id']])) ?>"><?= Namira\MobileNavigation::icon('user') ?><span>مشاهده صفحه شهید <?= e(P::personName($person)) ?></span></a><?php endforeach ?></nav><div class="image-utilities<?= empty($im['download_allowed'])?' no-download':'' ?>"><?php if(!empty($im['download_allowed'])): ?><a class="primary nm-icon-action" aria-label="دانلود تصویر" title="دانلود تصویر" href="<?= e(url('download',['id'=>$im['id']])) ?>"><?= Namira\MobileNavigation::icon('download') ?><span>دانلود</span></a><?php endif ?><?php view('share-tools',['sharePage'=>'image','shareId'=>$im['id'],'shareTitle'=>$humanTitle,'shareLabels'=>true]); ?></div></div></div></div>
